<?php
declare(strict_types=1);
namespace Ecrm\Storage;
use RuntimeException;
final class AtomicJsonStore { public function __construct(private string $root){} public function put(string $collection,string $id,array $record):void{$dir=$this->dir($collection);$this->ensure($dir);$lock=fopen($dir.'/.lock','c+');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Storage lock failed');try{$path=$dir.'/'.$id.'.json';$tmp=$path.'.'.bin2hex(random_bytes(5)).'.tmp';$json=json_encode($record,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);if(file_put_contents($tmp,$json."\n",LOCK_EX)===false)throw new RuntimeException('Storage write failed');if(!rename($tmp,$path))throw new RuntimeException('Atomic publish failed');}finally{flock($lock,LOCK_UN);fclose($lock);}} public function get(string $collection,string $id):?array{$p=$this->dir($collection).'/'.$id.'.json';if(!is_file($p))return null;return json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);} public function all(string $collection):array{$dir=$this->dir($collection);if(!is_dir($dir))return[];$out=[];foreach(glob($dir.'/*.json')?:[] as $p)$out[]=json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);return$out;} private function dir(string $c):string{if(!preg_match('/^[a-z][a-z0-9_-]*$/',$c))throw new RuntimeException('Invalid collection');return rtrim($this->root,'/').'/'.$c;} private function ensure(string $d):void{if(!is_dir($d)&&!mkdir($d,0770,true)&&!is_dir($d))throw new RuntimeException('Cannot create storage');}}
